  if (at(["diff", "--no-ext-diff", "--no-textconv", "--quiet", `${target}...${head}`]).status === 0) return "empty-diff";
  const trees = (ref: string) => at(["rev-parse", "--verify", "--quiet", "--end-of-options", `${ref}^{tree}`]).stdout.trim();
